use verus::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> Vec<u64>
    ensures
        // The result length is the sum of input lengths
        result.len() == a.len() + b.len()
    ensures
        // For every index in a, result[i] equals a[i]
        forall|i: usize| (i < a.len()) ==> result[i] == a[i]
    ensures
        // For every index in b, result[a.len() + i] equals b[i]
        forall|i: usize| (i < b.len()) ==> result[a.len() + i] == b[i]
{
    // input lengths bounded by 100
    // (Assuming callers respect this, or you can add requires)
    let len_a = a.len();
    let len_b = b.len();

    // allocate vector with capacity len_a + len_b, initially empty
    let mut res = Vec::<u64>::empty();

    // Append all elements from a
    let mut i = 0;
    while i < len_a
        invariant i <= len_a
        invariant res.len() == i
        invariant forall|j: usize| (j < i) ==> res[j] == a[j]
    {
        res.push(a[i]);
        i = i + 1;
    }

    // Append all elements from b
    let mut j = 0;
    while j < len_b
        invariant j <= len_b
        invariant res.len() == len_a + j
        invariant forall|k: usize| (k < len_a) ==> res[k] == a[k]
        invariant forall|k: usize| (k < j) ==> res[len_a + k] == b[k]
    {
        res.push(b[j]);
        j = j + 1;
    }

    res
}

}